import{_ as t,o as s,c as o,a3 as n}from"./chunks/framework.cNy3aYYk.js";const m=JSON.parse('{"title":"Expense itemized lines (expenses 1.7.0) — Production Readiness","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Expense itemized lines (expenses 1.7.0) — Production Readiness | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/expense-lines-1-7-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Expense itemized lines (expenses 1.7.0) — Production Readiness | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/expense-lines-1-7-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/expense-lines-1-7-0-production-readiness.md","filePath":"deployment/expense-lines-1-7-0-production-readiness.md","lastUpdated":1792527715000}'),r={name:"deployment/expense-lines-1-7-0-production-readiness.md"};function a(d,e,i,c,l,p){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="expense-itemized-lines-expenses-1-7-0-—-production-readiness" tabindex="-1">Expense itemized lines (expenses 1.7.0) — Production Readiness <a class="header-anchor" href="#expense-itemized-lines-expenses-1-7-0-—-production-readiness" aria-label="Permalink to &quot;Expense itemized lines (expenses 1.7.0) — Production Readiness&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-19</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> — Pest and headed Playwright green</td></tr><tr><td><strong>Scope</strong></td><td>Optional itemized expense lines. Header amount and tax are the sums. Pay still posts one journal debit</td></tr><tr><td><strong>Catalog</strong></td><td><strong>expenses 1.6.0 → 1.7.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="/user-guide/expenses">Expenses user guide</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Draft expenses can store up to 50 lines (description, amount, tax, category). The header amount and tax are rewritten from those lines. The header category is set only when every line shares one category; otherwise it is empty and the list, record, and sheet show <strong>Mixed</strong>. Creating without <code>lines</code> still stores a single header amount. Purchase-order convert copies each purchase-order line and splits the purchase-order tax across them. Mark as paid still debits one expense account for the gross.</p><p><strong>Go / No-Go:</strong> <strong>Go.</strong> Migrate-only (<code>expense_lines</code> plus the catalog bump). Existing expenses stay header-only until the next draft save. Do not <code>db:seed</code>.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze</td><td><strong>Pass</strong></td></tr><tr><td>Header-only create still stores amount and tax with no lines</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Lines recompute totals, clear a mixed category, and replace on update</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Category filter matches a line category</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Pay posts one debit of the gross</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Submitted expenses reject line edits</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Purchase-order convert splits tax across lines</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Catalog <strong>expenses 1.7.0</strong></td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Headed one session: empty title, description, and amount stay on the form; a second line with another category shows Mixed; edit updates the first amount; pay journal shows <code>6000</code> / <code>1000</code> and <code>$30.00</code>; category filter finds the expense; purchase-order convert shows the source line</td><td><strong>Pass</strong> (<code>npm run test:e2e:expenses:lines:headed</code>, 1 passed)</td></tr><tr><td>Headed expenses suite: lines, unpay, create/pay, receipt, and purchase-order convert</td><td><strong>Pass</strong> (5 passed; workflow rerun with <code>E2E_VIDEO=off</code> after ffmpeg was unavailable)</td></tr></tbody></table><h2 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h2><p>Reviewed <code>ExpenseService</code> line sync, pay journal, purchase-order convert, web and mobile forms, and the list category badge on 2026-10-19.</p><p>The first headed run failed because the local database had not migrated <code>expense_lines</code>. After <code>php artisan migrate</code>, the same session passed. The list previously showed an empty category for mixed lines; it now shows <strong>Mixed</strong>, matching the record page. Pay remains one journal. Reimbursement beyond paid is still deferred.</p><hr><h2 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h2><ol><li><code>php artisan migrate --force</code>. Do not <code>db:seed</code>.</li><li>Confirm <code>modules.version</code> for <code>expenses</code> is <code>1.7.0</code>.</li><li>Deploy Frontend after production build; hard-refresh SPA. Ship the mobile build with the same API.</li></ol>',13)])])}const u=t(r,[["render",a]]);export{m as __pageData,u as default};
